package com.servicerca.model;import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="app_notification") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class AppNotification{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(optional=false)@JoinColumn(name="user_id")private User user;@ManyToOne@JoinColumn(name="request_id")private ServiceRequest request;@Column(nullable=false,length=60)private String type;@Column(nullable=false,length=500)private String message;@Column(name="read_at")private Instant readAt;@Column(name="created_at",nullable=false)private Instant createdAt;@PrePersist void pre(){if(createdAt==null)createdAt=Instant.now();}}
